import React from "react";

const Contact = () => {
  return (
    <div className="container my-4">
      <h2 className="display-5 fw-bold mb-3">📞 Contact Us</h2>
      <form>
        <input type="text" placeholder="Name" className="form-control my-2" />
        <input type="email" placeholder="Email" className="form-control my-2" />
        <textarea placeholder="Message" className="form-control my-2"></textarea>
        <button className="btn btn-dark mt-2">Send</button>
      </form>
    </div>
  );
};

export default Contact;
