import React, { useState, useEffect, useRef } from "react";
import "./Donation.css";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import "../fonts/Amiri-Regular-normal";
import arabic from "arabic-persian-reshaper";
import bidi from "bidi-js";




const plansData = [
  { title: "Sponsor an Aalim", price: 100000 },
  { title: "Sponsor a Hafiz", price: 100000 },
  { title: "Sponsor a Widow", price: 150000 },
  { title: "Aalim's Pocket Money", price: 90000 },
  { title: "Sponsor a Madrasa", price: 300000 },
  { title: "Sponsor an Islamic Preacher", price: 300000 }
];

const Donation = () => {
  const formRef = useRef(null);
  const receiptRef = useRef(null);
  const shareOnWhatsApp = () => {
  if (!receiptId) return;

  const message = `
🧾 *Donation Receipt*
*Misbahi Welfare Mission*

🆔 Receipt ID: ${receiptId}
📅 Date: ${timestamp}

👤 Name: ${formData.name}
💰 Amount: INR ${formData.amount}
🎯 Purpose: ${formData.type}

May Allah accept your charity 🤲
`;

  const encodedMessage = encodeURIComponent(message);

  const whatsappURL = `https://wa.me/?text=${encodedMessage}`;

  window.open(whatsappURL, "_blank");
};


  const [selectedPlan, setSelectedPlan] = useState(null);
  const [counters, setCounters] = useState({
    widows: 0,
    aalims: 0,
    women: 0,
    men: 0
  });

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    contact: "",
    amount: "",
    type: ""
  });

  const [receiptId, setReceiptId] = useState("");
  const [timestamp, setTimestamp] = useState("");
  const [showReceipt, setShowReceipt] = useState(false);

  // Animated Counter Effect
  useEffect(() => {
    const interval = setInterval(() => {
      setCounters((prev) => ({
        widows: prev.widows < 63 ? prev.widows + 1 : 63,
        aalims: prev.aalims < 179 ? prev.aalims + 3 : 179,
        women: prev.women < 2080 ? prev.women + 25 : 2080,
        men: prev.men < 1250 ? prev.men + 20 : 1250
      }));
    }, 30);

    return () => clearInterval(interval);
  }, []);

  const handlePlanSelect = (plan) => {
    setSelectedPlan(plan.title);
    setFormData({ ...formData, amount: plan.price });
    formRef.current.scrollIntoView({ behavior: "smooth" });
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    const id = "MWM-" + Math.floor(100000 + Math.random() * 900000);
    setReceiptId(id);
    setTimestamp(new Date().toLocaleString());
    setShowReceipt(true);
  };

const formatArabic = (text) => {
  const reshaped = arabic.reshape(text);
  const bidiText = bidi.fromString(reshaped).toString();
  return bidiText;
};



  // 📄 Download PDF
const downloadPDF = () => {
  if (!receiptId) return;

  const pdf = new jsPDF("p", "mm", "a4");
  const pageWidth = pdf.internal.pageSize.getWidth();
  let y = 20;

  // ===== HEADER =====
  pdf.setFillColor(0, 128, 96);
  pdf.rect(0, 0, pageWidth, 30, "F");

  pdf.setTextColor(255, 255, 255);
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(18);
  pdf.text("Misbahi Welfare Mission", pageWidth / 2, 15, { align: "center" });

  pdf.setFontSize(11);
  pdf.text("Official Donation Receipt", pageWidth / 2, 23, { align: "center" });

  pdf.setTextColor(0, 0, 0);
  y = 40;

  // ===== ARABIC TOP =====
  pdf.setFont("Amiri", "normal");
  pdf.setFontSize(16);

  const bismillah = formatArabic("بِسْمِ ٱللَّٰهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ");
  pdf.text(bismillah, pageWidth - 20, y, { align: "right" });

  y += 12;

  pdf.setDrawColor(0, 128, 96);
  pdf.line(20, y, pageWidth - 20, y);

  y += 15;

  // ===== RECEIPT META =====
  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(11);

  pdf.text(`Receipt ID: ${receiptId}`, 20, y);
  pdf.text(`Date: ${timestamp}`, pageWidth - 20, y, { align: "right" });

  y += 15;

  // ===== DONOR INFO =====
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(13);
  pdf.text("Donor Information", 20, y);

  y += 8;

  pdf.setFont("helvetica", "normal");
  pdf.setFontSize(11);

  pdf.text(`Full Name: ${formData.name}`, 25, y); y += 7;
  pdf.text(`Email Address: ${formData.email}`, 25, y); y += 7;
  pdf.text(`Contact Number: ${formData.contact}`, 25, y); y += 7;
  pdf.text(`Donation Purpose: ${formData.type}`, 25, y);

  y += 18;

  // ===== AMOUNT BOX =====
  pdf.setFillColor(0, 200, 83);
  pdf.roundedRect(20, y, pageWidth - 40, 18, 5, 5, "F");

  pdf.setTextColor(255, 255, 255);
  pdf.setFont("helvetica", "bold");
  pdf.setFontSize(14);
  pdf.text(
    `Total Amount Received: INR ${formData.amount}`,
    pageWidth / 2,
    y + 11,
    { align: "center" }
  );

  pdf.setTextColor(0, 0, 0);
  y += 30;

  // ===== ARABIC THANKS =====
  pdf.setFont("Amiri", "normal");
  pdf.setFontSize(15);

  const jazakallah = formatArabic("جَزَاكَ ٱللَّٰهُ خَيْرًا");
  pdf.text(jazakallah, pageWidth - 20, y, { align: "right" });

  y += 12;

  // ===== DUA =====
  pdf.setFont("helvetica", "italic");
  pdf.setFontSize(11);

  pdf.text(
    "May Allah (SWT) accept your charity and reward you abundantly.",
    pageWidth / 2,
    y,
    { align: "center" }
  );

  y += 6;

  pdf.text(
    "May He grant you barakah in wealth and Jannatul Firdaus. Ameen.",
    pageWidth / 2,
    y,
    { align: "center" }
  );

  y += 25;

  // ===== FOOTER =====
  pdf.setFontSize(9);
  pdf.setTextColor(100);
  pdf.text(
    "Misbahi Welfare Mission | Serving Humanity for the Sake of Allah",
    pageWidth / 2,
    285,
    { align: "center" }
  );

  pdf.save(`MWM_Donation_${receiptId}.pdf`);
};










// 🖨 Print Receipt
const printReceipt = () => {
  const printContents = receiptRef.current.innerHTML;
  const newWindow = window.open("", "", "width=900,height=650");
  newWindow.document.write(`
    <html>
      <head>
        <title>Print Receipt</title>
        
      </head>
      <body>
        ${printContents}
      </body>
    </html>
  `);
  newWindow.document.close();
  newWindow.print();
};


  const whatsappMessage = `
🧾 Donation Receipt
Misbahi Welfare Mission

Receipt ID: ${receiptId}
Date: ${timestamp}

Name: ${formData.name}
Amount: £${formData.amount}
Purpose: ${selectedPlan || formData.type}

Thank you for supporting humanity 💚
`;

  return (
    <div className="donation-wrapper py-5">
      <div className="container">

        {/* HEADER */}
        <div className="text-center mb-5">
          <h1 className="fw-bold donation-title">
            Jaamiah Mueeniyyah Azharul Uloom
          </h1>
          <p className="text-muted">
            A state-of-the-art all-girls Islamic institution in India.
          </p>
        </div>

        {/* SPONSORSHIP PLANS */}
        <div className="row g-4 mb-5">
          {plansData.map((plan, index) => (
            <div className="col-md-4" key={index}>
              <div
                className={`plan-card p-4 text-center ${
                  selectedPlan === plan.title ? "active-plan" : ""
                }`}
              >
                <h5>{plan.title}</h5>
                <h3 className="text-success my-3">₹{plan.price} / Year</h3>
                
              </div>
            </div>
          ))}
        </div>

        {/* PROGRESS SECTION */}
        <div className="progress-section text-center p-5 mb-5">
          <h3 className="mb-4">Our Progress</h3>
          <div className="row">
            <div className="col-md-3">
              <h2>{counters.widows}</h2>
              <p>Widows</p>
            </div>
            <div className="col-md-3">
              <h2>{counters.aalims}</h2>
              <p>Aalim Students</p>
            </div>
            <div className="col-md-3">
              <h2>{counters.women}</h2>
              <p>Teaching Events (Women)</p>
            </div>
            <div className="col-md-3">
              <h2>{counters.men}</h2>
              <p>Teaching Events (Men)</p>
            </div>
          </div>
        </div>

        {/* DONATION FORM */}
        <div ref={formRef} className="form-card p-5 mb-5">
          <h4 className="mb-4 text-center">Complete Your Sponsorship</h4>

          <form onSubmit={handleSubmit}>
            <input
              type="text"
              name="name"
              placeholder="Full Name"
              className="form-control mb-3"
              onChange={handleChange}
              required
            />

            <input
              type="email"
              name="email"
              placeholder="Email"
              className="form-control mb-3"
              onChange={handleChange}
              required
            />

            <input
              type="text"
              name="contact"
              placeholder="Mobile Number"
              className="form-control mb-3"
              onChange={handleChange}
              required
            />

            <input
              type="number"
              name="amount"
              value={formData.amount}
              placeholder="Amount (£)"
              className="form-control mb-3"
              onChange={handleChange}
              required
            />

            <select
              name="type"
              className="form-control mb-4"
              onChange={handleChange}
            >
              <option value="">Select Donation Type</option>
              <option value="Lillah">Lillah</option>
              <option value="Zakat">Zakat</option>
              <option value="Fitra">Fitra</option>
              <option value="Sadqah">Sadqah</option>
            </select>

            <button className="btn btn-success w-100">
              Generate Receipt
            </button>
          </form>
        </div>

        {/* RECEIPT */}
{showReceipt && (
  <div className="receipt-overlay">
    <div ref={receiptRef} className="receipt-modal ultra-receipt">

      <button
        className="close-btn"
        onClick={() => setShowReceipt(false)}
      >
        ✕
      </button>

<div className="receipt-header">
  <h2>Misbahi Welfare Mission</h2>
  <p className="receipt-sub">Official Donation Receipt</p>
</div>

<div className="arabic-top">
  بِسْمِ ٱللَّٰهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
</div>

<div className="receipt-meta">
  <div><strong>Receipt ID:</strong> {receiptId}</div>
  <div><strong>Date:</strong> {timestamp}</div>
</div>

<div className="divider" />

<div className="donor-section">
  <h5>Donor Information</h5>
  <p><strong>Full Name:</strong> {formData.name}</p>
  <p><strong>Email Address:</strong> {formData.email}</p>
  <p><strong>Contact Number:</strong> {formData.contact}</p>
  <p><strong>Donation Purpose:</strong> {formData.type}</p>
</div>

<div className="amount-section">
  Total Amount Received: INR {formData.amount}
</div>

<div className="arabic-bottom">
  جَزَاكَ ٱللَّٰهُ خَيْرًا
</div>

<p className="dua-text">
  May Allah (SWT) accept your charity, grant barakah in your wealth,
  and reward you with Jannatul Firdaus. Ameen.
</p>

<div className="signature-area">
  Authorised Signature
  <br />
  <small>
    This is a computer-generated receipt and does not require a physical signature.
  </small>
</div>

<div className="footer-note">
  Misbahi Welfare Mission | Serving Humanity for the Sake of Allah
</div>
      <div className="btn-group mt-4 d-flex gap-2 justify-content-center">
  <button onClick={downloadPDF} className="btn btn-primary">
    Download PDF
  </button>

  <button onClick={shareOnWhatsApp} className="btn btn-success">
    Share on WhatsApp
  </button>
</div>
<button onClick={shareOnWhatsApp} className="btn btn-success">
  <i className="bi bi-whatsapp me-2"></i>
  Share on WhatsApp
</button>

      <div className="btn-group mt-4">
        <button onClick={downloadPDF} className="btn btn-primary">
          Download PDF
        </button>
      </div>

    </div>
  </div>
)}




        <div className="text-center mt-5 small text-muted">
          © Misbahi Welfare Mission
        </div>

      </div>
    </div>
  );
};

export default Donation;
