import React from "react";

export default function Library() {



  // ✅ FEATURE CARDS
  const items = [

    {
      title: "🎧 Audio Books",
      desc: "Listen to MP3 Islamic lectures & audiobooks.",
      points: ["Play Online", "Download MP3", "By Topic", "By Speaker"],
      color: "bg-light",
    },
  ];

  return (
    <div className="container my-5">






      {/* ================= FEATURE CARDS ================= */}
      <div className="row g-4">
        {items.map((box, index) => (
          <div className="col-md-4" key={index}>
            <div
              className={`p-4 rounded shadow-sm h-100 ${box.color}`}
              style={{ transition: "0.3s", cursor: "pointer" }}
              onMouseEnter={(e) =>
                (e.currentTarget.style.transform = "scale(1.03)")
              }
              onMouseLeave={(e) =>
                (e.currentTarget.style.transform = "scale(1)")
              }
            >
              <h4 className="fw-bold">{box.title}</h4>
              <p className="text-muted small">{box.desc}</p>

              <ul className="mt-3">
                {box.points.map((p, i) => (
                  <li key={i}>{p}</li>
                ))}
              </ul>

            </div>
          </div>
        ))}
      </div>

    </div>
  );
}
